<?php
require __DIR__ . '/data/pets.php';
$page = 'pets';
function renderCard(array $pet): string {
    $name = htmlspecialchars($pet['name'], ENT_QUOTES, 'UTF-8');
    return '<article class="pet-card"><img src="' . htmlspecialchars($pet['image'], ENT_QUOTES, 'UTF-8') . '" alt="' . $name . ', ' . htmlspecialchars($pet['breed'], ENT_QUOTES, 'UTF-8') . '"><div class="pet-body"><div class="pet-topline"><span>' . htmlspecialchars($pet['species']) . '</span><span>' . htmlspecialchars($pet['status']) . '</span></div><div class="pet-bottom"><h3>' . $name . '</h3><button class="heart" data-favorite="' . $pet['id'] . '" aria-label="Save ' . $name . '">♡</button></div><p class="pet-breed">' . htmlspecialchars($pet['breed']) . ' · ' . htmlspecialchars($pet['age']) . '</p><p class="pet-location">⌖ ' . htmlspecialchars($pet['location']) . '</p><div class="pet-bottom"><span class="fee">$' . $pet['fee'] . ' adoption fee</span><a class="button button-light" href="pet.php?id=' . $pet['id'] . '">Meet ' . $name . '</a></div></div></article>';
}
